#include <bits/stdc++.h>
using namespace std;

static const int MAXN=1e6+5;
static const int M1=998244353;
static const int M2=1e9+7;
static const int B=1000000;

long long n;
vector<int> seqs[10];
long long count=0;
int prefixSumArr[10];
int result=0;

void generate(int level,int val){
    seqs[level].push_back(((++count)-val+M1)%M1);
    prefixSumArr[level]+=seqs[level].back()%M2;
    prefixSumArr[level]%=M2;
    if(level==6) return;
    for(int i=0;i<=9;i++) generate(level+1,10*val+i);
}

void compute(long long x){
    if(x>n) return;
    if(x*B+B-1<=n && x*B*10>n){
        long long rk=count;
        for(int i=0,step=1;i<=6;i++,step*=10){
            int delta=((rk - x*step)%M1+M1)%M1;
            int pos=lower_bound(seqs[i].begin(),seqs[i].end(),-delta+M1)-seqs[i].begin();
            result+=((1LL*delta*seqs[i].size()%M2+prefixSumArr[i])%M2 - 1LL*(seqs[i].size()-pos)*M1%M2 +M2)%M2;
            result%=M2;
            count+=seqs[i].size();
        }
        return;
    }
    result+=(((++count)-x)%M1+M1)%M1;
    result%=M2;
    for(int i=0;i<=9;i++) compute(x*10+i);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    generate(0,0);
    for(int i=0;i<=6;i++) sort(seqs[i].begin(),seqs[i].end());
    count=0;
    for(int i=1;i<=9;i++) compute(i);
    cout << result << "\n";
    return 0;
}
